import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(fileURLToPath(new URL('.', import.meta.url)), '..');
const output = join(root, 'js', 'app.bundle.js');

// Dependency order for the browser bundle. The human-readable source stays split
// into modules; this generated classic script also works when index.html is opened
// directly from disk, where browsers reject ES-module imports for security reasons.
const modules = [
  'js/config.js',
  'js/core/random.js',
  'js/data/chapters.js',
  'js/data/i18n.js',
  'js/data/roles.js',
  'js/data/ingredients.js',
  'js/data/events.js',
  'js/data/tasks.js',
  'js/core/timers.js',
  'js/core/audio.js',
  'js/core/storage.js',
  'js/core/game-engine.js',
  'js/ui/helpers.js',
  'js/ui/dialog.js',
  'js/ui/welcome.js',
  'js/ui/game.js',
  'js/ui/overlays.js',
  'js/app.js'
];

function convertModule(source, relativePath) {
  const importsRemoved = source.replace(/^import\s+[^;]+;\s*$/gm, '');
  const exportsRemoved = importsRemoved.replace(/^export\s+(?=(?:const|let|var|function|class)\b)/gm, '');
  if (/^\s*(?:import|export)\b/m.test(exportsRemoved)) {
    throw new Error(`Unsupported module syntax in ${relativePath}`);
  }
  return `\n/* ${relativePath} */\n${exportsRemoved.trim()}\n`;
}

const sections = [];
for (const relativePath of modules) {
  const source = await readFile(join(root, relativePath), 'utf8');
  sections.push(convertModule(source, relativePath));
}

const bundle = `/* Generated by tools/build-bundle.mjs. Edit the modular source files, not this file. */
(function adventureDinnerApplication() {
  'use strict';
${sections.join('\n')}
})();
`;

await mkdir(dirname(output), { recursive: true });
await writeFile(output, bundle, 'utf8');
console.log(`Built ${output}`);
